import json, re
d = json.load(open('/private/tmp/claude-501/-Users-taha/c7a33960-1c96-4b0c-b15f-02a996414e54/scratchpad/materials.json'))
sections = d.get('primaryContentSections', [])
def extract_text(node):
    out = []
    if isinstance(node, dict):
        if node.get('type') == 'text' and 'text' in node:
            out.append(node['text'])
        for k,v in node.items():
            out.extend(extract_text(v))
    elif isinstance(node, list):
        for item in node:
            out.extend(extract_text(item))
    return out

texts = extract_text(sections)
full = ' '.join(texts)
print('refract count:', len(re.findall(r'refract', full, re.I)))
print('opacity count:', len(re.findall(r'opacity', full, re.I)))
for m in re.finditer(r'opacity', full, re.I):
    print('...', full[max(0,m.start()-100):m.start()+100], '...')
